<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>{{ $seoTitle ?? 'The Clinic — Personal care, simply booked' }}</title>
  <meta name="description" content="{{ $seoDescription ?? 'A modern, personal clinic experience with simple online appointment booking.' }}">
  <link rel="canonical" href="{{ url()->current() }}">
  <meta name="theme-color" content="#071c40">
