    <style>[x-cloak] { display: none !important; }</style>
  @endif
  <style>
    /* Critical clinic identity styles: intentionally available before the asset build. */
    .clinic-header { position:absolute; top:0; left:0; width:100%; z-index:50; padding:22px 20px 0; transition:padding .25s ease; }
    .clinic-header.is-stuck { position:fixed; padding-top:10px; animation:clinicNavIn .28s ease-out; }
    .clinic-nav { max-width:1240px; height:72px; margin:auto; display:flex; align-items:center; justify-content:space-between; gap:24px; padding:0 18px 0 22px; background:rgba(255,255,255,.92); border:1px solid rgba(255,255,255,.88); border-radius:22px; box-shadow:0 20px 55px -32px rgba(31,55,110,.42); backdrop-filter:blur(20px); }
    .clinic-brand { display:flex; align-items:center; gap:10px; color:#0d1220; text-decoration:none; font-size:22px; line-height:1; font-weight:800; letter-spacing:-.075em; }
    .clinic-mark { display:grid; width:40px; height:40px; place-items:center; border-radius:14px; color:#fff; font-size:20px; font-weight:800; background:linear-gradient(135deg,#3b82f6,#8b5cf6); box-shadow:0 10px 20px -12px rgba(59,130,246,.85); }
    .clinic-brand em { color:#3b82f6; font-style:normal; }
    .clinic-links { display:flex; align-items:center; gap:4px; }
    .clinic-links a,.clinic-actions a { border-radius:12px; padding:10px 14px; color:#4b5563; text-decoration:none; font-size:14px; font-weight:600; transition:.2s ease; }
    .clinic-links a:hover,.clinic-actions .login-link:hover { color:#111827; background:#f5f7fb; }
    .clinic-links .active { color:#2563eb; background:#eff6ff; }
    .clinic-actions { display:flex; align-items:center; gap:2px; }
    .clinic-actions .book-link { margin-left:6px; padding:12px 18px; color:#fff; background:#3b82f6; box-shadow:0 12px 22px -14px rgba(37,99,235,.85); font-weight:700; }
    .clinic-actions .book-link:hover { color:#fff; background:#2563eb; transform:translateY(-1px); }
    .clinic-mobile { display:none; border:1px solid #e5e7eb; border-radius:12px; background:#fff; width:40px; height:40px; color:#111827; }
    .clinic-mobile-menu { max-width:1240px; margin:8px auto 0; padding:12px; border-radius:18px; background:#fff; border:1px solid #eef2f7; box-shadow:0 18px 45px -30px rgba(31,55,110,.42); }
    .clinic-mobile-menu a { display:block; padding:12px 14px; color:#374151; border-radius:11px; font-weight:600; text-decoration:none; }.clinic-mobile-menu a:hover{background:#f5f7fb}.clinic-mobile-menu .mobile-book{margin-top:6px;text-align:center;background:#3b82f6;color:#fff}
    .home-hero { position:relative; isolation:isolate; overflow:hidden; margin-top:0; padding:154px 0 32px; background:radial-gradient(circle at 8% 24%,rgba(139,92,246,.16),transparent 26%),radial-gradient(circle at 87% 25%,rgba(59,130,246,.20),transparent 31%),linear-gradient(180deg,#f8fbff 0%,#edf4ff 100%); }
    .home-hero:before { content:""; position:absolute; inset:0; z-index:-1; opacity:.55; background-image:linear-gradient(rgba(59,130,246,.075) 1px,transparent 1px),linear-gradient(90deg,rgba(59,130,246,.075) 1px,transparent 1px); background-size:44px 44px; mask-image:linear-gradient(to bottom,#000,transparent 88%); }
    .hero-orbit { position:absolute; z-index:-1; border:1px solid rgba(59,130,246,.13); border-radius:999px; }.hero-orbit-a{width:500px;height:500px;right:-210px;top:82px}.hero-orbit-b{width:290px;height:290px;left:-130px;bottom:15px}
    @keyframes clinicNavIn{from{transform:translateY(-15px);opacity:.4}to{transform:translateY(0);opacity:1}}@media(max-width:1023px){.clinic-header{padding:12px 12px 0}.clinic-nav{height:64px;padding:0 14px;border-radius:18px}.clinic-links,.clinic-actions{display:none}.clinic-mobile{display:grid;place-items:center}.home-hero{margin-top:0;padding-top:112px}}
