  <script>
    document.addEventListener('DOMContentLoaded', function () {
      var items=document.querySelectorAll('.reveal'); var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}})},{threshold:.12});document.querySelectorAll('main > section').forEach(function(section){if(!section.classList.contains('reveal')){section.classList.add('reveal')}});items=document.querySelectorAll('.reveal');items.forEach(function(item){observer.observe(item)});
      document.querySelectorAll('[data-review-slider]').forEach(function(slider){var track=slider.querySelector('.review-track'),cards=[].slice.call(slider.querySelectorAll('.review-card')),dots=[].slice.call(slider.querySelectorAll('.review-dot')),index=0,timer;function perView(){return innerWidth<=620?1:innerWidth<=900?2:3}function render(){var max=Math.max(0,cards.length-perView());index=Math.min(index,max);track.style.transform='translateX(calc(-'+index+' * (100% + 18px) / '+perView()+'))';dots.forEach(function(dot,i){dot.classList.toggle('active',i===index)})}function start(){clearInterval(timer);timer=setInterval(function(){var max=Math.max(0,cards.length-perView());index=index>=max?0:index+1;render()},3000)}dots.forEach(function(dot,i){dot.addEventListener('click',function(){index=i;render();start()})});addEventListener('resize',render);slider.addEventListener('mouseenter',function(){clearInterval(timer)});slider.addEventListener('mouseleave',start);render();start()});
    });
  </script>
